// Firewall range-sync test (task T045; the file is generated by T057). ADR-0001 §3 with
// Amendment 3: NON_PUBLIC_IPV4_RANGES is the single source of truth, and the NL-2 firewall list
// `ops/firewall/nonpublic-ipv4.txt` must contain exactly the same ranges.
//
// File format expected from T057: one IPv4 CIDR per line; blank lines and lines starting with `#`
// (for example a "generated from NON_PUBLIC_IPV4_RANGES" header) are ignored.
import { existsSync, readFileSync } from "node:fs";
import ipaddr from "ipaddr.js";
import { describe, expect, it } from "vitest";
import { NON_PUBLIC_IPV4_RANGES } from "../../src/url-policy/ip-classify.ts";

const FILE = new URL("../../../../ops/firewall/nonpublic-ipv4.txt", import.meta.url);

const ranges = () =>
  readFileSync(FILE, "utf8")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line !== "" && !line.startsWith("#"));

describe("ops/firewall/nonpublic-ipv4.txt matches NON_PUBLIC_IPV4_RANGES", () => {
  it("the file exists (generated by T057)", () => {
    expect(existsSync(FILE), "ops/firewall/nonpublic-ipv4.txt").toBe(true);
  });

  it("every line is a valid IPv4 CIDR", () => {
    for (const line of ranges()) expect(ipaddr.IPv4.isValidCIDR(line), line).toBe(true);
  });

  it("contains exactly the same ranges, with no duplicates", () => {
    const file = ranges();
    expect(new Set(file).size, "duplicate lines").toBe(file.length);
    expect([...file].sort()).toEqual([...NON_PUBLIC_IPV4_RANGES].sort());
  });
});
